import{_ as r,I as n,c as o,o as i,ag as a,J as s}from"./chunks/framework.ARG558ZT.js";const f=JSON.parse('{"title":"Application and transport security boundaries","description":"","frontmatter":{},"headers":[],"relativePath":"engineering/security.md","filePath":"engineering/security.md"}'),c={name:"engineering/security.md"};function _(d,e,h,l,u,p){const t=n("MermaidDiagram");return i(),o("div",null,[e[0]||(e[0]=a('<h1 id="application-and-transport-security-boundaries" tabindex="-1">Application and transport security boundaries <a class="header-anchor" href="#application-and-transport-security-boundaries" aria-label="Permalink to “Application and transport security boundaries”">​</a></h1><p><strong>Prerequisites:</strong> HTTP methods/status, unknown-input validation, identity and asynchronous lifetimes. Review baseline: 2026-10-27. All learner practice remains outstanding.</p><h2 id="begin-with-actor-resource-and-sink" tabindex="-1">Begin with actor, resource and sink <a class="header-anchor" href="#begin-with-actor-resource-and-sink" aria-label="Permalink to “Begin with actor, resource and sink”">​</a></h2><p><a href="./../senior_growth/Communication_and_Security/Can_you_provide_several_examples_of_Web_Security_related_issues__like_types_of_attack__and_how_can_we_prevent_them__OWASP_10.html">Threat model and OWASP editions</a> → <a href="./../senior_growth/Communication_and_Security/What_authentication_authorization_mechanisms_do_you_use_on_your_project_Please_describe_how_they_work.html">Authentication versus authorization</a>. Derive the principal server-side and enforce owner/tenant/version in the actual operation. OWASP Top 10:2025 is an awareness taxonomy, not a complete verification standard.</p><h2 id="choose-one-browser-transport" tabindex="-1">Choose one browser transport <a class="header-anchor" href="#choose-one-browser-transport" aria-label="Permalink to “Choose one browser transport”">​</a></h2><p><a href="./../senior_growth/Communication_and_Security/Where_do_you_prefer_to_store_auth_token__Where_is_it_most_secure.html">Token/session placement</a> → <a href="./../senior_growth/Communication_and_Security/What_is_CORS__Can_proper_CORS_configuration_protect_against_CSRF_attacks__What_other_measures_can_be_taken_to_mitigate_CSRF_attacks.html">CORS and CSRF</a> → <a href="./../senior_growth/Communication_and_Security/Do_you_remember_any_security_headers.html">Headers and nonces</a>. Cookie attachment, credentialed CORS, CSRF policy and protected mutations need their own checks. HttpOnly limits token reads, not every authenticated action by hostile script.</p><h2 id="protect-protocol-and-data-lifecycle" tabindex="-1">Protect protocol and data lifecycle <a class="header-anchor" href="#protect-protocol-and-data-lifecycle" aria-label="Permalink to “Protect protocol and data lifecycle”">​</a></h2><p><a href="./../senior_growth/Communication_and_Security/HTTPS._Could_you_please_describe_advantages_and_disadvantages_of_this_protocol.html">TLS boundaries</a>; <a href="./../senior_growth/Communication_and_Security/Could_you_please_provide_me_a_detailed_explanation_about_HTTP_verbs.html">HTTP method semantics</a>; <a href="./../senior_growth/Communication_and_Security/RESTful_API_HTTP__and_WebSockets_-_why_and_when_we_need_them._Limitations.html">Bounded WebSocket ownership</a>. TLS authenticates/protects a hop; it does not authorize a record. Transport closure does not establish remote rollback.</p><h2 id="use-the-canonical-implementations" tabindex="-1">Use the canonical implementations <a class="header-anchor" href="#use-the-canonical-implementations" aria-label="Permalink to “Use the canonical implementations”">​</a></h2><p>The <a href="./../node-js/module-09-authentication-authorization.html">Node authorization course</a>, <a href="./../node-js/retention-and-deletion.html">retention/deletion</a> and <a href="./../frontend/next.html">Next boundary</a> own server/database implementation. These browser/HTTP notes complement them, rather than create a second authentication system.</p><h2 id="shared-authority-boundary" tabindex="-1">Shared authority boundary <a class="header-anchor" href="#shared-authority-boundary" aria-label="Permalink to “Shared authority boundary”">​</a></h2>',11)),s(t,{"encoded-source":"flowchart%20TD%0A%20%20Browser%5BUntrusted%20browser%20input%5D%20--%3E%20Parse%5BBound%20and%20validate%20request%5D%0A%20%20Parse%20--%3E%20Actor%5BResolve%20current%20server%20identity%5D%0A%20%20Actor%20--%3E%20Write%5BAuthorize%20resource%20and%20version%20in%20operation%5D%0A%20%20Write%20--%3E%20Store%5BDatabase%20constraints%20and%20commit%5D%0A%20%20Store%20--%3E%20Reply%5BSafe%20projected%20response%5D"}),e[1]||(e[1]=a('<p>Parsing, actor identity and operation authorization answer separate questions. A validated field or a hidden UI button cannot replace the later checks.</p><h2 id="practice-and-verification" tabindex="-1">Practice and verification <a class="header-anchor" href="#practice-and-verification" aria-label="Permalink to “Practice and verification”">​</a></h2><p>Use <a href="./../practice/engineering/">the shared increments</a> and linked focused requirements. <a href="./../workbench/engineering/">Workbench</a> contains canonical references; <a href="./../review/verification.html">verification</a> distinguishes current checks, preserved historical evidence and unperformed integrations.</p>',3))])}const y=r(c,[["render",_]]);export{f as __pageData,y as default};
